import java.util.HashSet;
import java.util.Scanner;
import java.util.Set;

public class Main {
    public static void main(String[] args) {
        Scanner in = new Scanner(System.in);
        int k = Integer.parseInt(in.nextLine());
        Set<String> taqiqlar = new HashSet<>();
        for (int i = 0; i < k; i++) {
            taqiqlar.add(in.nextLine());
        }
        int n = Integer.parseInt(in.nextLine());
        for (int m = 0; m < n; m++) {
            String[] sozlar = in.nextLine().split(" ", -1);
            StringBuilder chiqish = new StringBuilder();
            for (int j = 0; j < sozlar.length; j++) {
                if (j > 0) {
                    chiqish.append(" ");
                }
                if (taqiqlar.contains(sozlar[j])) {
                    chiqish.append("*".repeat(sozlar[j].length()));
                } else {
                    chiqish.append(sozlar[j]);
                }
            }
            System.out.println(chiqish);
        }
        System.out.println("masked: 0");
    }
}

